<script setup lang="ts">
import {ref,watch} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;csv:string;parameters:Record<string,number>}>();const emit=defineEmits<{apply:[csv:string]}>();
const horizons=ref([{name:'近期',year:2028,growth:.05,wind_scale:1.05,pv_scale:1.05,noise:.03},{name:'中期',year:2030,growth:.18,wind_scale:1.25,pv_scale:1.3,noise:.04},{name:'远期',year:2035,growth:.35,wind_scale:1.55,pv_scale:1.7,noise:.05}]);
const seed=ref(42);const records=ref<any[]>([]);const selected=ref<any>(null);const busy=ref(false);const error=ref('');const horizon=ref(0);
async function refresh(){const id=props.projectId;if(!id)return;const r=await fetch('/api/source-studies?project_id='+id);if(!r.ok)throw Error('读取源荷研究失败');const data=await r.json();if(id===props.projectId)records.value=data}
watch(()=>props.projectId,()=>{selected.value=null;records.value=[];error.value='';refresh().catch(e=>error.value=String(e))},{immediate:true});
async function run(){busy.value=true;error.value='';const id=props.projectId;try{const r=await fetch('/api/source-studies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:id,csv:props.csv,seed:seed.value,horizons:horizons.value,critical_ratio:props.parameters.critical_load_ratio,important_ratio:props.parameters.important_load_ratio})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(id===props.projectId){selected.value=d;horizon.value=0;await refresh()}}catch(e){if(id===props.projectId)error.value=String(e)}finally{busy.value=false}}
function url(kind:string){return '/api/source-studies/'+selected.value.id+'/csv?horizon='+horizon.value+'&kind='+kind}
async function apply(){const id=props.projectId;busy.value=true;error.value='';try{const r=await fetch(url('annual'));if(!r.ok)throw Error('年度数据读取失败');const csv=await r.text();if(id===props.projectId)emit('apply',csv.replace(/^\uFEFF/,''))}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><article><h3>近中远期源荷与全年背景</h3><p>调用课题2原始分解、分位边界、分级负荷及年度重采样代码，按建设年份分别保存输出。运行阶段仍在平衡分析中单独设置。</p><p>下列为研究代码示例参数，请按项目水平年修改。历史数据缺少某月份时原算法回退全样本，不代表该月份已得到验证。</p><div class="scroll"><table><tr><th>水平年</th><th>年份</th><th>负荷增长比例</th><th>风电缩放</th><th>光伏缩放</th><th>扰动标准差</th></tr><tr v-for="h in horizons"><td><input v-model="h.name" :disabled="busy"></td><td><input v-model.number="h.year" type="number" :disabled="busy"></td><td v-for="key in (['growth','wind_scale','pv_scale','noise'] as const)"><input v-model.number="h[key]" type="number" step=".01" :disabled="busy"></td></tr></table></div><label class="field">随机种子<input v-model.number="seed" type="number" :disabled="busy"></label><button @click="run" :disabled="busy||!projectId">{{busy?'正在生成并归档…':'生成三个水平年研究'}}</button><p class="error" v-if="error">{{error}}</p><h3>已保存研究</h3><button v-for="r in records" class="record" @click="selected=r;horizon=0">{{r.created}} · {{r.horizons.map((h:any)=>h.name).join(' / ')}} · {{r.id.slice(0,8)}}</button><template v-if="selected"><p>{{selected.scope}}</p><p>历史输入摘要 {{selected.input_sha256.slice(0,16)}}；工程版本 {{selected.project_revision}}。下方始终显示归档时的参数与结果。</p><label class="field">结果水平年<select v-model.number="horizon"><option v-for="(h,i) in selected.horizons" :value="i">{{h.name}} · {{h.year}}</option></select></label><table><tr><th>小时数</th><th>峰值负荷 / kW</th><th>全年负荷电量 / kWh</th></tr><tr><td>{{selected.horizons[horizon].hours}}</td><td>{{selected.horizons[horizon].peak_load_kw.toFixed(2)}}</td><td>{{selected.horizons[horizon].load_energy_kwh.toFixed(2)}}</td></tr></table><div class="actions"><a :href="url('annual')">全年背景CSV</a><a :href="url('classified')">分级负荷CSV</a><a :href="url('load_boundary')">负荷分位边界CSV</a><a :href="url('renewable_boundary')">风光分位边界CSV</a><a :href="url('decomposition')">多尺度分解CSV</a></div><button @click="apply" :disabled="busy">将此水平年全年背景应用到工程</button><p>应用会替换当前时序并解除旧场景与生产序列引用。8760小时请使用汇总模型；IEEE33交互模型限168小时，可先提取极端窗口。</p><details><summary>前24小时预览</summary><div class="scroll"><table><tr><th>时间</th><th>负荷kW</th><th>风电kW</th><th>光伏kW</th></tr><tr v-for="r in selected.horizons[horizon].preview"><td>{{r.timestamp}}</td><td>{{r.load_kw.toFixed(2)}}</td><td>{{r.wind_kw.toFixed(2)}}</td><td>{{r.pv_kw.toFixed(2)}}</td></tr></table></div></details></template></article></template>
<style scoped>td input{width:100px;padding:8px;border:1px solid #c8dcdf}.actions{flex-wrap:wrap;margin:18px 0;gap:16px}</style>
